"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["63130"],{36503(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_incompleta","status":422,"titulo":"A resolu\xe7\xe3o de Pesos por \xc1rea n\xe3o tem pesos para todos os grupos de \xe1rea"},"descricao":{"codigo":"uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_incompleta","requisitos":[],"oQueAconteceu":["Na classifica\xe7\xe3o baseada em ENEM com c\xe1lculo local pela m\xe9dia ponderada, a resolu\xe7\xe3o\\ninformada em `resolucaoPesoAreaEnem` existe no cadastro de Pesos por \xc1rea (Configura\xe7\xe3o), mas\\nn\xe3o tem linha de pesos para todos os grupos de \xe1rea. A mensagem do erro traz a resolu\xe7\xe3o e os\\nr\xf3tulos dos grupos que faltam. S\xf3 quem conhece todos os grupos de \xe1rea \xe9 o cadastro de\\nConfigura\xe7\xe3o; a classifica\xe7\xe3o congela uma c\xf3pia dos pesos de cada grupo, e por isso exige a\\nresolu\xe7\xe3o completa.","A recusa vem no campo `resolucaoPesoAreaEnem` e acumula, na mesma resposta, com as demais\\nviola\xe7\xf5es da classifica\xe7\xe3o. Resolu\xe7\xe3o sem nenhuma linha \xe9 recusada em\\n[`resolucao_peso_area_enem_nao_encontrada`](/erros/uniplus.selecao.configuracao_classificacao.resolucao_peso_area_enem_nao_encontrada)."],"comoResolver":["Cadastre, no cadastro de Pesos por \xc1rea (Configura\xe7\xe3o), os pesos dos grupos listados na\\nmensagem para essa resolu\xe7\xe3o, e envie a defini\xe7\xe3o da classifica\xe7\xe3o de novo. Se a resolu\xe7\xe3o\\ninformada n\xe3o era a pretendida, informe outra que tenha pesos para todos os grupos."],"ondeAparece":["Defini\xe7\xe3o de classifica\xe7\xe3o do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao classificacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);